// Vendored platform contract tooling: `pull <file>`, `types`, `check`.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const contractPath = resolve(root, "contract/openapi.json");
const typesPath = resolve(root, "src/lib/api/schema.d.ts");

const HEADER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

async function generate() {
  const contract = JSON.parse(readFileSync(contractPath, "utf8"));
  const ast = await openapiTS(contract);
  return HEADER + astToString(ast);
}

async function types() {
  writeFileSync(typesPath, await generate());
  console.log("wrote src/lib/api/schema.d.ts");
}

async function pull(file) {
  if (!file) {
    fail("usage: node scripts/contract.mjs pull <file>");
  }
  let contract;
  try {
    contract = JSON.parse(readFileSync(resolve(file), "utf8"));
  } catch (error) {
    fail(`cannot read ${file} as JSON: ${error.message}`);
  }
  if (typeof contract?.openapi !== "string" || !contract.openapi.startsWith("3.1")) {
    fail(`${file} is not an OpenAPI 3.1 document`);
  }
  writeFileSync(contractPath, `${JSON.stringify(contract, null, 2)}\n`);
  console.log("wrote contract/openapi.json");
  await types();
}

async function check() {
  const expected = await generate();
  if (!existsSync(typesPath) || readFileSync(typesPath, "utf8") !== expected) {
    fail("src/lib/api/schema.d.ts is out of date: run pnpm contract:types");
  }
}

function fail(message) {
  console.error(message);
  process.exit(1);
}

const [command, ...args] = process.argv.slice(2);
const commands = { pull, types, check };
if (!Object.hasOwn(commands, command ?? "")) {
  fail("usage: node scripts/contract.mjs <pull <file>|types|check>");
}
await commands[command](...args);
